 events:['События',()=>'<div class="card"><b>🏰 Осада Sdolars</b><p>Победи 10 врагов. Прогресс: <b>'+state.eventProgress+'/10</b></p><button class="goldBtn" onclick="eventFight()">Участвовать</button></div><div class="card"><b>⚔️ Турнир арены</b><p>Сразись с другими бойцами.</p><button onclick="toast(&quot;Турнир скоро начнётся&quot;)">Подробнее</button></div>'],
 vip:['VIP',()=>'<div class="card"><b>👑 VIP Sdolars</b><p>Статус: <b>'+state.vip+'</b></p><p>VIP даёт дополнительные награды, скидки и ускоренное восстановление.</p><button class="goldBtn" onclick="toast(&quot;VIP-магазин будет открыт после подключения сервера&quot;)">Открыть VIP</button></div>'],
 messages:['Чат',renderChat],
 ach:['Достижения',()=>'<div class="card"><b>🏆 Первый бой</b><p>Победи первого противника.</p><p>Прогресс: <b>'+(state.wins>0?'1':'0')+' / 1</b></p></div><div class="card"><b>💰 Богач</b><p>Накопи 2000 монет.</p><p>Прогресс: <b>'+Math.min(state.coins,2000)+' / 2000</b></p></div><div class="card"><b>⚔️ Воин Sdolars</b><p>Победи 10 противников.</p><p>Прогресс: <b>'+state.wins+' / 10</b></p></div>'],
