      const b={id,playerId:pid,enemyIndex:idx,enemy:e,playerHp:Math.min(Number(s.hp)||s.maxHp,s.maxHp),maxPlayerHp:s.maxHp,enemyHp:e.hp,turn:1,done:false,createdAt:Date.now()};
